/**
 * 入库缓冲（文件队列）
 *
 * 每个入库事件写一个独立 JSON 文件，避免多个 execution 并发修改
 * workflow static data 时互相覆盖、随机丢集数。
 *
 * 需要 n8n 允许 fs：在 stack.env 里加
 *   NODE_FUNCTION_ALLOW_BUILTIN=fs
 * 没有 fs 权限时：直接输出 bark 立即逐条发送（不聚合，但不丢消息）。
 */

// 缓冲目录，默认放在 n8n 的 .n8n 数据卷里；要换路径改这里
const BUFFER_DIR = "/home/node/.n8n/transfer_buffer";

const items = $input.all();
if (!items.length) return [];

let fs = null;
try {
    fs = require("fs");
} catch (e) {
    fs = null;
}

const payloads = items
    .map((item) => item.json)
    .filter((json) => json && json.transfer && json.transfer.kind === "episode" && json.bark);

// 没有 fs 权限：不聚合，直接发，避免静默丢消息
if (!fs) {
    console.log("入库聚合: 没有 fs 权限（需 NODE_FUNCTION_ALLOW_BUILTIN=fs），本次逐条发送");
    return payloads.map((json) => ({ json: { bark: json.bark, source: json.source, event: json.event } }));
}

try {
    fs.mkdirSync(BUFFER_DIR, { recursive: true });
    for (const json of payloads) {
        const stamp = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
        const final = `${BUFFER_DIR}/${stamp}.json`;
        const tmp = `${final}.tmp`;
        fs.writeFileSync(tmp, JSON.stringify({ at: Date.now(), transfer: json.transfer, bark: json.bark }));
        fs.renameSync(tmp, final);
    }
} catch (error) {
    // 写文件失败也退回逐条发送，避免丢通知
    console.log(`入库聚合: 写缓冲失败（${error.message}），本次逐条发送`);
    return payloads.map((json) => ({ json: { bark: json.bark, source: json.source, event: json.event } }));
}

return [];
